(x, y, t) => {
  const src = [
    [160+Math.sin(t*.6)*100, 80+Math.cos(t*.4)*50],
    [320+Math.cos(t*.5)*100, 160+Math.sin(t*.7)*50],
    [240+Math.sin(t*.3+2)*140, 120+Math.cos(t*.5+1)*90],
    [100+Math.cos(t*.8+3)*80, 190+Math.sin(t*.6+2)*60],
    [380+Math.sin(t*.4+5)*90, 50+Math.cos(t*.9+1)*40]
  ];
  const fr=[.08,.1,.06,.09,.07], sp=[2,1.7,2.3,1.5,1.9];
  let act=0, inh=0;
  for(let i=0;i<5;i++){
    const d=Math.sqrt((x-src[i][0])**2+(y-src[i][1])**2);
    const w=Math.sin(d*fr[i]-t*sp[i]+i*1.3);
    i<3?act+=w:inh+=w;
  }
  act/=3; inh/=2;
  const bg=(Math.sin(x*.05+y*.03+t*.8)+Math.sin(x*.03-y*.05+t*1.1))/2;
  const fine=(Math.sin((x+y)*.15+t*3)+Math.sin((x-y)*.12-t*2.5))*.15;
  const rx=act-inh*.8+fine;
  const spot=Math.tanh(rx*2.5);
  const wx=x+Math.sin(rx*3+t)*18, wy=y+Math.cos(rx*2.5+t*.7)*18;
  const wp=Math.tanh((Math.sin(wx*.04-t*1.2)+Math.sin(wy*.035+t*.9)+Math.sin(Math.atan2(y-120,x-240)*3-Math.sqrt((x-240)**2+(y-120)**2)*.02+t*.8)*.3)*1.8);
  const dist=Math.sqrt((x-240)**2+(y-120)**2);
  const p2=Math.tanh((Math.sin(dist*.04-t*1.5)+Math.sin(Math.atan2(y-120,x-240)*6+t*.4)*.5)*2);
  const micro=Math.sin(x*.18+rx*5)*Math.sin(y*.18-rx*4)*.08;
  const edge=1-Math.abs(spot)*.15-Math.abs(p2)*.1;
  const v=(spot*.32+p2*.22+wp*.32+micro+bg*.04)*.5+.5;
  const pal=[[6,12,42],[12,58,105],[20,135,125],[60,185,155],[200,190,70],[235,145,45],[190,55,40],[60,15,50],[6,12,42]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=(.78+Math.sin(rx*Math.PI)*.22)*(1-Math.pow(dist/300,3)*.45)*edge;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum)|0
  ];
}
